import re

import pytest

from kagent.config import REPO_ROOT
from kagent.deps.lockfile import (
    add_requirement,
    normalize,
    parse_lock,
    requirement_names,
    sandbox_versions,
)

DOCKER = REPO_ROOT / "docker"

LOCK = """\
# autogenerated
numpy==2.4.6 ; python_full_version < '3.12' \\
    --hash=sha256:aaa
numpy==2.5.4 ; python_full_version >= '3.12' \\
    --hash=sha256:bbb
pandas==2.3.3 \\
    --hash=sha256:ccc
tzdata==2026.5 ; sys_platform == 'win32' \\
    --hash=sha256:ddd
    # via pandas
Scikit_Learn==1.9.1 \\
    --hash=sha256:eee
"""


def test_parse_lock_picks_the_pin_for_the_sandbox_platform():
    pins = parse_lock(LOCK)
    assert pins == {"numpy": "2.4.6", "pandas": "2.3.3", "scikit-learn": "1.9.1"}


def test_normalize_follows_pep_503():
    assert normalize("Scikit_Learn") == normalize("scikit.learn") == "scikit-learn"


def test_requirement_names_skip_comments_and_constraints():
    assert requirement_names("# top\nlightgbm\npandas>=2.2,<3\n\n") == ["lightgbm", "pandas"]


def test_add_requirement_appends_and_replaces():
    text = "# c\nlightgbm\npandas>=2.2,<3\n"
    added = add_requirement(text, "catboost", ">=1.2")
    assert added.splitlines() == ["# c", "lightgbm", "pandas>=2.2,<3", "catboost>=1.2"]
    replaced = add_requirement(added, "CatBoost", "")
    assert replaced.splitlines()[-1] == "CatBoost" and replaced.lower().count("catboost") == 1


def test_real_sandbox_versions_come_from_the_lock():
    versions = sandbox_versions(DOCKER)
    assert set(versions) == {"lightgbm", "numpy", "pandas", "scikit-learn"}
    assert versions["pandas"].startswith("2.")  # pandas 3 breaks the idioms the models know


def _entries(text):
    """(name, block) for every pinned entry in a compiled lock."""
    parts = re.split(r"(?m)^(?=[A-Za-z0-9][A-Za-z0-9._-]*==)", text)
    return [(p.split("==")[0], p) for p in parts if "==" in p.split("\n")[0]]


@pytest.mark.parametrize("name", ["sandbox", "grader"])
def test_every_locked_package_has_hashes(name):
    entries = _entries((DOCKER / f"{name}.lock.txt").read_text())
    assert len(entries) > 10
    assert [n for n, block in entries if "--hash=sha256:" not in block] == []


def test_grader_and_sandbox_share_the_same_data_stack():
    sandbox = parse_lock((DOCKER / "sandbox.lock.txt").read_text())
    grader = parse_lock((DOCKER / "grader.lock.txt").read_text())
    for name in ("numpy", "pandas", "scikit-learn"):
        assert sandbox[name] == grader[name]


@pytest.mark.parametrize("name", ["sandbox", "grader"])
def test_dockerfiles_install_only_from_the_hashed_lock(name):
    dockerfile = (DOCKER / f"{name}.Dockerfile").read_text()
    assert f"COPY docker/{name}.lock.txt" in dockerfile
    assert "pip install --no-cache-dir --require-hashes -r /tmp/requirements.txt" in dockerfile
    assert len(re.findall(r"pip install", dockerfile)) == 1  # nothing installed outside the lock
